(53, 'Pride and Prejudice', 'প্রাইড অ্যান্ড প্রেজুডিস', 'A Classic Novel of Manners', '0141439513', '9780141439518', 27, 2002, 'Penguin Classics Edition', 'English', 'Follows the character development of Elizabeth Bennet, who learns about the repercussions of hasty judgments and Mr. Darcy''s true nature.');

