(54, 'Revolution 2020', 'রেভলিউশন ২০২০', 'Love, Corruption, Ambition', '8129118920', '9788129118929', 30, 2011, '1st Edition', 'English', 'A story about childhood friends Gopal, Raghav, and Aarti who struggle to find success and love in the corrupt education system of Varanasi.'),
(55, 'One Arranged Murder', 'ওয়ান অ্যারেঞ্জড মার্ডার', 'A gripping murder mystery', '9388754093', '9789388754095', 31, 2020, '1st Edition', 'English', 'Keshav and Saurabh investigate the mysterious death of Saurabh''s fiancée Prerna on the night of Karva Chauth.'),
(56, 'Introduction to Algorithms', 'ইন্ট্রোডাকশন টু অ্যালগরিদমস', 'Comprehensive Text on Modern Algorithms', '0262033844', '9780262033848', 32, 2009, '3rd Edition', 'English', 'In-depth coverage of a broad range of algorithms in design and analysis, accessible to all levels of readers.'),
(57, 'Clean Code', 'ক্লিন কোড', 'A Handbook of Agile Software Craftsmanship', '0132350882', '9780132350884', 33, 2008, '1st Edition', 'English', 'Instills the values of a software craftsman and teaches the best practices of writing readable, maintainable, and clean code.'),
(58, 'Head First Java', 'হেড ফার্স্ট জাভা', 'A Brain-Friendly Guide', '0596009208', '9780596009205', 34, 2005, '2nd Edition', 'English', 'Combines puzzles, strong visuals, mysteries, and soul-searching interviews with famous Java objects to engage you in learning Java.'),
(59, 'The Pragmatic Programmer', 'দ্য প্র্যাগম্যাটিক প্রোগ্রামার', 'Your Journey to Mastery', '0135957052', '9780135957059', 35, 2019, '20th Anniversary Edition', 'English', 'Cuts through the increasing specialization and technicalities of modern software development to examine the core process.'),
(60, 'Java: The Complete Reference', 'জাভা: দ্য কমপ্লিট রেফারেন্স', 'Comprehensive Guide to the Java Language', '1260440230', '9781260440232', 5, 2018, '11th Edition', 'English', 'Fully updated for Java SE 11, explaining how to develop, compile, debug, and run Java programs effectively.'),
(61, 'Effective Java', 'ইফেক্টিভ জাভা', 'Best Practices for the Java Platform', '0134685997', '9780134685991', 35, 2017, '3rd Edition', 'English', 'Brings together seventy-eight indispensable programmer''s rules of thumb: working, best-practice solutions for the programming challenges.'),
(62, 'Design Patterns', 'ডিজাইন প্যাটার্নস', 'Elements of Reusable Object-Oriented Software', '0201633612', '9780201633610', 35, 1994, '1st Edition', 'English', 'Captures a wealth of experience about the design of object-oriented software through 23 classic Gang of Four design patterns.'),
(63, 'The Mythical Man-Month', 'দ্য মিথিক্যাল ম্যান-মান্থ', 'Essays on Software Engineering', '0201835959', '9780201835953', 35, 1995, 'Anniversary Edition', 'English', 'A blend of software engineering facts and thought-provoking opinions on managing complex projects and software teams.'),
(64, 'Refactoring', 'রিফ্যাক্টরিং', 'Improving the Design of Existing Code', '0134757599', '9780134757591', 35, 2018, '2nd Edition', 'English', 'Explains the principles of refactoring and demonstrates how to transform messy code into well-structured, maintainable systems.'),
(65, 'You Don''t Know JS', 'ইউ ডোন্ট নো জেএস', 'Up & Going', '1491904240', '9781491904244', 34, 2015, '1st Edition', 'English', 'Dives deep into the core mechanisms of the JavaScript language, including scope, closures, prototypes, and async patterns.'),
(66, 'Eloquent JavaScript', 'ইলোকুয়েন্ট জাভাস্ক্রিপ্ট', 'A Modern Introduction to Programming', '1593279507', '9781593279509', 36, 2018, '3rd Edition', 'English', 'Dives into the JavaScript language to show you how to write beautiful, effective code with practical projects.'),
(67, 'Python Crash Course', 'পাইথন ক্র্যাশ কোর্স', 'A Hands-On, Project-Based Introduction to Programming', '1593279280', '9781593279288', 36, 2019, '2nd Edition', 'English', 'A fast-paced, thorough introduction to programming with Python that will have you writing programs and solving problems quickly.'),
(68, 'Automate the Boring Stuff with Python', 'অটোমেট দ্য বোরিং স্টাফ উইথ পাইথন', 'Practical Programming for Total Beginners', '1593279922', '9781593279929', 36, 2019, '2nd Edition', 'English', 'Teaches how to use Python to write programs that do in minutes what would take you hours to do by hand.'),
(69, 'The Lean Startup', 'দ্য লিন স্টার্টআপ', 'How Today''s Entrepreneurs Use Continuous Innovation', '0307887898', '9780307887894', 37, 2011, '1st Edition', 'English', 'Provides a scientific approach to creating and managing successful startups in an age when companies need to innovate more than ever.'),
(70, 'Zero to One', 'জিরো টু ওয়ান', 'Notes on Startups, or How to Build the Future', '0804139296', '9780804139298', 37, 2014, '1st Edition', 'English', 'Presents an optimistic view of the future of progress in America and a new way of thinking about innovation: it starts by learning to ask the questions that lead you to find value in unexpected places.'),
(71, 'Start With Why', 'স্টার্ট উইথ হোয়াই', 'How Great Leaders Inspire Everyone to Take Action', '1591846447', '9781591846444', 38, 2009, 'Reprint Edition', 'English', 'Shows that the leaders who''ve had the greatest influence in the world all think, act, and communicate the exact same way—by starting with why.'),
(72, 'The Subtle Art of Not Giving a F*ck', 'দ্য সাটল আর্ট অব নট গিভিং আ ফাক', 'A Counterintuitive Approach to Living a Good Life', '0062457713', '9780062457714', 39, 2016, '1st Edition', 'English', 'Argues that improving our lives hinges not on our ability to turn lemons into lemonade, but on learning to stomach lemons better.'),
(73, 'Ikigai', 'ইকিগাই', 'The Japanese Secret to a Long and Happy Life', '0143130722', '9780143130727', 40, 2017, 'International Edition', 'English', 'Explores the Japanese concept of finding your purpose and meaning in life, inspired by the centenarians of Okinawa.'),
(74, 'The Power of Habit', 'দ্য পাওয়ার অব হ্যাবিট', 'Why We Do What We Do in Life and Business', '081298160X', '9780812981605', 41, 2014, 'Trade Paperback', 'English', 'Takes us to the thrilling edge of scientific discoveries that explain why habits exist and how they can be changed.'),
(75, 'Sapiens', 'স্যাপিয়েন্স', 'A Brief History of Humankind', '0062316095', '9780062316097', 39, 2015, '1st Edition', 'English', 'Explores how the currents of history have shaped our human societies, the animals and plants around us, and even our personalities.'),
(76, 'Homo Deus', 'হোমো ডিউস', 'A Brief History of Tomorrow', '0062464310', '9780062464316', 39, 2017, '1st Edition', 'English', 'Examines what might happen to the world when old myths are coupled with new godlike technologies such as artificial intelligence and genetic engineering.'),
(77, '21 Lessons for the 21st Century', '২১ লেসনস ফর দ্য ২১স্ট সেঞ্চুরি', 'Meditations on the Present Global Challenges', '0525512179', '9780525512172', 42, 2018, '1st Edition', 'English', 'Probes today''s most urgent issues including technological disruption, fake news, terrorism, and the future of liberal democracy.'),
(78, 'Thinking, Fast and Slow', 'থিংকিং, ফাস্ট অ্যান্ড স্লো', 'The Two Systems That Drive the Way We Think', '0374533555', '9780374533557', 43, 2013, 'Paperback Edition', 'English', 'Nobel laureate Daniel Kahneman explains the two systems that drive the way we think: System 1 is fast and emotional; System 2 is slower and logical.'),
(79, 'The Intelligent Investor', 'দ্য ইন্টেলিজেন্ট ইনভেস্টর', 'The Definitive Book on Value Investing', '0060555661', '9780060555665', 44, 2006, 'Revised Edition', 'English', 'Teaches the philosophy of value investing, which shields investors from substantial error and teaches them to develop long-term strategies.'),
(80, 'A Brief History of Time', 'আ ব্রিফ হিস্ট্রি অব টাইম', 'From the Big Bang to Black Holes', '0553380168', '9780553380163', 45, 1998, '10th Anniversary Edition', 'English', 'A landmark volume in science writing explaining cosmology, black holes, time travel, and the search for a unified theory of the universe.'),
(81, 'Cosmos', 'কসমস', 'Exploring the Universe, Science, and Civilization', '0345539435', '9780345539434', 46, 2013, 'Reprint Edition', 'English', 'Retraces the fourteen billion years of cosmic evolution that have transformed matter into consciousness and explores the history of science.'),
(82, 'The Selfish Gene', 'দ্য সেলফিশ জিন', 'The Gene-Centered View of Evolution', '0198788606', '9780198788607', 47, 2016, '40th Anniversary Edition', 'English', 'Reformulates the theory of natural selection from the perspective of the gene, illustrating how altruistic behavior can evolve.'),
(83, 'Brief Answers to the Big Questions', 'ব্রিফ আনসারস টু দ্য বিগ কোয়েশ্চেনস', 'Final Thoughts on the Universe', '1984819194', '9781984819192', 45, 2018, '1st Edition', 'English', 'Posthumously published collection of Stephen Hawking''s final thoughts on humanity''s biggest questions about space, AI, and the cosmos.'),
(84, 'Hijibiji', 'হিজিবিজি', 'ব্যক্তিগত স্মৃতিচারণ ও রম্যরচনা', '9848685552', '9789848685555', 12, 2013, '4th Edition', 'Bangla', 'হুমায়ূন আহমেদের জীবনের নানা মজার ঘটনা, সাহিত্যিকদের সান্নিধ্য ও ব্যক্তিগত অভিজ্ঞতার সরস গদ্য সংকলন।'),
(85, 'Megher Chaya', 'মেঘের ছায়া', 'সমসাময়িক সামাজিক উপন্যাস', '9848685668', '9789848685666', 12, 1993, '7th Edition', 'Bangla', 'মানবিক সম্পর্ক, ভুল বোঝাবুঝি ও মমতার ছায়া ঘেরা মধ্যবিত্ত পরিবারের সংবেদনশীল আখ্যান।'),
(86, 'Ochinpur', 'অচিনপুর', 'শৈশব ও বিষাদময় জীবনের গল্প', '9848685773', '9789848685777', 12, 1999, '6th Edition', 'Bangla', 'এক বালকের চোখ দিয়ে দেখা পরিবারের ভাঙন, মায়ের অসুস্থতা ও কল্পনার জগতের বিষাদময় উপন্যাস।'),
(87, 'Botol Bhoot', 'বোতল ভূত', 'শিশু-কিশোরদের মজার ভূতের গল্প', '9848685889', '9789848685888', 12, 1989, '10th Edition', 'Bangla', 'দুষ্টু বালক হুমায়ূন ও তার উপহার পাওয়া বোতলের ভেতর থাকা সদালাপী ভূতের মজার ও মায়াময় কিশোর উপন্যাস।'),
(88, 'Shrestho Himu', 'শ্রেষ্ঠ হিমু', 'নির্বাচিত হিমু উপন্যাস সংকলন', '9848685994', '9789848685999', 12, 2010, '5th Edition', 'Bangla', 'হিমু সিরিজের সবচেয়ে জনপ্রিয় কয়েকটি উপন্যাসের একত্র সংকলন।'),
(89, 'Science Fiction Somogro', 'সায়েন্স ফিকশন সমগ্র', 'কল্পবিজ্ঞান কাহিনী সংকলন', '9848686001', '9789848686000', 12, 2008, '6th Edition', 'Bangla', 'তোমাদের জন্য ভালোবাসা, তারা তিনজন, ইরিনা ও অন্যান্য জনপ্রিয় বৈজ্ঞানিক কল্পকাহিনীর সংকলন।'),
(90, 'Revive Your Heart', 'রিভাইভ ইয়োর হার্ট', 'হৃদয়ের প্রশান্তি ও আত্মশুদ্ধি', '9849450117', '9789849450111', 6, 2019, '2nd Edition', 'Bangla', 'আধুনিক জীবনের অস্থিরতা দূর করে প্রার্থনা ও কুরআনের আলোকে হৃদয়কে সজীব করার অনুপ্রেরণামূলক বই।'),
(91, 'Nobi Jiboner Golpo', 'নবি জীবনের গল্প', 'প্রিয় নবীর জীবনের শিক্ষণীয় ঘটনা', '9849450222', '9789849450222', 6, 2022, '1st Edition', 'Bangla', 'মহানবী হযরত মুহাম্মদ (সা.)-এর জীবনের টুকরো টুকরো হৃদয়স্পর্শী ঘটনা ও তার প্রাসঙ্গিক শিক্ষা।'),
(92, 'Shamayele Tirmidhi', 'শামায়েলে তিরমিজি', 'রাসূলুল্লাহ (সা.)-এর অবয়ব ও জীবনযাত্রা', '9849450338', '9789849450333', 7, 2016, '3rd Edition', 'Bangla', 'রাসূলুল্লাহ (সা.)-এর শারীরিক গঠন, পোশাক, আচার-আচরণ ও দৈনন্দিন সুন্নাত সম্পর্কিত হাদীস সংকলন।'),
(93, 'Sahih Masnoon Wazifa', 'সহীহ মাসনূন ওযীফা', 'প্রতিদিনের সুন্নাতসম্মত দুআ ও আমল', '9848683452', '9789848683456', 7, 2014, '8th Edition', 'Bangla', 'রাহে বেলায়াত গ্রন্থ থেকে সংকলিত সহীহ হাদীস ভিত্তিক প্রতিদিনের জরুরি দুআ ও যিকরের সংক্ষিপ্ত পুস্তিকা।'),
(94, 'Al Quran Ek Mohabismoy', 'আল কুরআন এক মহাবিস্ময়', 'কুরআন ও আধুনিক বিজ্ঞান', '9849011881', '9789849011888', 8, 2010, '6th Edition', 'Bangla', 'ফরাসি চিকিৎসক ড. মরিস বুকাইলির গবেষণায় পবিত্র কুরআনের বাণী ও আধুনিক বিজ্ঞানের বিস্ময়কর সামঞ্জস্যের আলোচনা।'),
(95, 'How to Talk to Anyone', 'হাউ টু টক টু এনিওয়ান', 'যে কারো সাথে কথা বলার ৯২টি কৌশল', '984920177X', '9789849201777', 11, 2018, '3rd Edition', 'Bangla', 'সামাজিক ও পেশাগত জীবনে যেকোনো মানুষের সাথে আকর্ষণীয়ভাবে কথোপকথন ও সম্পর্ক গড়ার ব্যবহারিক কৌশল।'),
(96, 'Uddesshohin Ar Koto Din?', 'উদ্দেশ্যহীন আর কত দিন?', 'আত্মসমালোচনা ও তাওবার আহ্বান', '9849450443', '9789849450444', 9, 2020, '2nd Edition', 'Bangla', 'গাফিলতি ও অলসতা ঝেড়ে ফেলে জীবনের প্রকৃত উদ্দেশ্য চিনে নেওয়ার উদ্দীপনামূলক ইসলামী লেকচার সংকলন।'),
(97, 'Tini O Se', 'তিনি ও সে', 'রহস্য ও মানবিক সম্পর্কের উপন্যাস', '9848686117', '9789848686111', 12, 1995, '5th Edition', 'Bangla', 'মানুষের দ্বৈত সত্তা ও মনস্তাত্ত্বিক জটিলতা নিয়ে রচিত সংক্ষিপ্ত উপন্যাস।'),
(98, 'Mojar Bhoot', 'মজার ভূত', 'কিশোরদের নির্বাচিত ভূতের গল্প', '9848686222', '9789848686222', 12, 1997, '7th Edition', 'Bangla', 'ভয়ের পরিবর্তে কৌতুক ও বন্ধুত্বপূর্ণ আবহে লেখা কিশোরদের জন্য ভূতের গল্পের সংকলন।'),
(99, 'Rodonbhora E Bosonto', 'রোদনভরা এ বসন্ত', 'বিরহ ও ভালোবাসার উপন্যাস', '9848686338', '9789848686333', 12, 1998, '6th Edition', 'Bangla', 'মানব মনের অপ্রাপ্তি, প্রেম ও নিঃসঙ্গতার সুর নিয়ে রচিত রোমান্টিক উপন্যাস।'),
(100, 'Sedin Choitromas', 'সেদিন চৈত্রমাস', 'স্মৃতি ও সম্পর্কের উপন্যাস', '9848686443', '9789848686444', 12, 1999, '5th Edition', 'Bangla', 'চৈত্রমাসের তপ্ত আবহে গড়ে ওঠা মানবিক টানাপোড়েন ও অতীত স্মৃতির উপন্যাস।'),
(101, 'Don Quixote', 'ডন কিহোতে', 'The Ingenious Gentleman of La Mancha', '0142437239', '9780142437230', 27, 2003, 'Translated Edition', 'English', 'The adventures of a noble from La Mancha who reads so many chivalric romances that he loses his sanity and sets out to revive chivalry.'),
(102, 'The Odyssey', 'দ্য ওডিসি', 'The Epic Journey of Odysseus', '0140268863', '9780140268867', 27, 1997, 'Revised Translation', 'English', 'Ancient Greek epic poem following the Greek hero Odysseus, king of Ithaca, and his ten-year journey home after the Trojan War.'),
(103, 'Hamlet', 'হ্যামলেট', 'The Tragedy of Hamlet, Prince of Denmark', '0199535817', '9780199535811', 48, 2008, 'Annotated Edition', 'English', 'Prince Hamlet exacts revenge against his uncle Claudius, who has murdered Hamlet''s father in order to seize his throne.');

INSERT INTO books (id, title_en, title_bn, subtitle, isbn_10, isbn_13, publisher_id, publication_year, edition, language, description) VALUES
(104, 'Pride and Prejudice', 'প্রাইড অ্যান্ড প্রেজুডিস', 'Classic Novel of Manners and Marriage', '0140430725', '9780140430721', 27, 2003, 'Reprint Edition', 'English', 'A witty exploration of love, reputation, and class in Regency England centered around the spirited Elizabeth Bennet and Mr. Darcy.'),
(105, 'Jane Eyre', 'জেন আয়ার', 'An Autobiography', '0141441143', '9780141441146', 27, 2006, 'Penguin Classics Edition', 'English', 'Follows the emotions and experiences of orphan Jane Eyre, including her growth to adulthood and her love for Mr. Rochester, master of Thornfield Hall.'),
(106, 'Wuthering Heights', 'উদারিং হাইটস', 'A Tale of Passionate and Destructive Love', '0141439556', '9780141439556', 27, 2003, 'Definitive Edition', 'English', 'Chronicles the turbulent, obsessive relationship between Heathcliff and Catherine Earnshaw on the Yorkshire moors.'),
(107, 'Great Expectations', 'গ্রেট এক্সপেক্টেশনস', 'The Story of Pip''s Ambition and Redemption', '0141439564', '9780141439563', 27, 2002, 'Unabridged Edition', 'English', 'Depicts the education and moral development of an orphan nicknamed Pip in Kent and London in the early to mid-19th century.'),
(108, 'A Tale of Two Cities', 'আ টেল অব টু সিটিজ', 'London and Paris in the Era of Revolution', '0141439602-2', '9780141439600-2', 27, 2003, 'Penguin Classics Edition', 'English', 'Historical novel set in London and Paris before and during the French Revolution, culminating in Sydney Carton''s ultimate sacrifice.'),
(109, 'Moby-Dick', 'মবি-ডিক', 'Or, The Whale', '0142437247', '9780142437247', 27, 2003, 'Critical Edition', 'English', 'Sailor Ishmael''s narrative of the obsessive quest of Ahab, captain of the whaling ship Pequod, for revenge on Moby Dick, the giant white sperm whale.'),
(110, 'Alice''s Adventures in Wonderland', 'অ্যালিসেস অ্যাডভেঞ্চারস ইন ওয়ান্ডারল্যান্ড', 'And Through the Looking-Glass', '0141439769', '9780141439761', 27, 2003, 'Illustrated Edition', 'English', 'A young girl named Alice falls through a rabbit hole into a subterranean fantasy world populated by peculiar, anthropomorphic creatures.'),
(111, 'Little Women', 'লিটল উইমেন', 'The Story of the March Sisters', '0147514010', '9780147514011', 27, 2014, 'Puffin in Bloom Edition', 'English', 'Follows the lives of the four March sisters—Meg, Jo, Beth, and Amy—and details their passage from childhood to womanhood.'),
(112, 'Adventures of Huckleberry Finn', 'অ্যাডভেঞ্চারস অব হাকলবেরি ফিন', 'Tom Sawyer''s Comrade', '0142437174', '9780142437179', 27, 2002, 'Penguin Classics Edition', 'English', 'A boy and a runaway slave named Jim drift down the Mississippi River on a raft, confronting the hypocrisy of antebellum society.'),
(113, 'The Picture of Dorian Gray', 'দ্য পিকচার অব ডোরিয়ান গ্রে', 'A Gothic and Philosophical Novel', '0199535981', '9780199535989', 48, 2008, 'Revised Edition', 'English', 'Dorian Gray sells his soul to ensure that a painted portrait of himself will age and bear the marks of his sins while he remains eternally young.'),
(114, 'Dracula', 'ড্রাকুলা', 'The Classic Gothic Vampire Novel', '014143984X', '9780141439846', 27, 2003, 'Annotated Edition', 'English', 'Told through letters, diary entries, and newspaper articles, detailing Count Dracula''s attempt to move from Transylvania to England.'),
(115, 'Frankenstein', 'ফ্র্যাঙ্কেনস্টাইন', 'Or, The Modern Prometheus', '0141439475', '9780141439471', 27, 2003, '1818 Text Edition', 'English', 'Victor Frankenstein, a young scientist, creates a sapient creature in an unorthodox scientific experiment and faces tragic consequences.'),
(116, 'Les Misérables', 'লা মিজারেবল', 'A Masterpiece of Compassion and Social Justice', '0140444300', '9780140444308', 27, 1982, 'Unabridged Edition', 'English', 'Examines the nature of law and grace as ex-convict Jean Valjean struggles to redeem himself while pursued by Inspector Javert.'),
(117, 'Crime and Punishment', 'ক্রাইম অ্যান্ড পানিশমেন্ট', 'A Psychological Study of Guilt and Redemption', '0140449132', '9780140449136', 27, 2002, 'McDuff Translation', 'English', 'Focuses on the mental anguish and moral dilemmas of Rodion Raskolnikov, an impoverished ex-student in Saint Petersburg who plans to kill an unscrupulous pawnbroker.'),
(118, 'War and Peace', 'ওয়ার অ্যান্ড পিস', 'Russian Society During the Napoleonic Era', '0140447938', '9780140447934', 27, 2006, 'Briggs Translation', 'English', 'Chronicles the French invasion of Russia and the impact of the Napoleonic era on Tsarist society through the stories of five Russian aristocratic families.'),
(119, 'The Brothers Karamazov', 'দ্য ব্রাদার্স কারামাজভ', 'A Passionate Philosophical Novel', '0140449248', '9780140449242', 27, 2003, 'Penguin Classics Edition', 'English', 'Enters deeply into ethical debates of God, free will, and morality through a spiritual drama of patricide and family rivalry in 19th-century Russia.'),
(120, 'Anna Karenina', 'আন্না কারেনিনা', 'A Complex Novel of Family Life and Passion', '0140449175', '9780140449174', 27, 2002, 'Pevear & Volokhonsky Translation', 'English', 'Deals with themes of betrayal, faith, family, marriage, Imperial Russian society, desire, and rural vs. city life.'),
(121, 'The Metamorphosis', 'দ্য মেটামরফোসিস', 'And Other Stories', '0141182903', '9780141182902', 27, 2000, 'Modern Classics Edition', 'English', 'Salesman Gregor Samsa wakes one morning to find himself inexplicably transformed into a huge insect and struggles to adjust to this new condition.'),
(122, 'The Trial', 'দ্য ট্রায়াল', 'A Surrealist Tale of Bureaucracy and Alienation', '0805209999', '9780805209990', 49, 1995, 'Definitive Edition', 'English', 'Tells the story of Josef K., a man arrested and prosecuted by a remote, inaccessible authority, with the nature of his crime revealed neither to him nor to the reader.'),
(123, 'The Stranger', 'দ্য স্ট্রেঞ্জার', 'Classic of Existentialist Literature', '0679720200', '9780679720201', 50, 1989, 'Ward Translation', 'English', 'Through the story of an ordinary man unwittingly drawn into a senseless murder on an Algerian beach, Camus explores what he termed the nakedness of man faced with the absurd.'),
(124, 'The Plague', 'দ্য প্লেগ', 'A Novel of Resilience and Solidarity', '0679720219', '9780679720218', 50, 1991, 'Gilbert Translation', 'English', 'Tells the story from the point of view of a narrator of a plague sweeping the French Algerian city of Oran and the human response to crisis.'),
(125, '1984', '১৯৮৪', 'Big Brother Is Watching You', '0451524934-2', '9780451524935-2', 51, 1961, 'Centennial Edition', 'English', 'Winston Smith wrestles with oppression in Oceania, a place where the Thought Police scrutinize human actions with ever-watchful Big Brother.'),
(126, 'Animal Farm', 'অ্যানিম্যাল ফার্ম', 'A Political Satire', '0141036133', '9780141036137', 52, 2008, 'Modern Classics Edition', 'English', 'Reflects events leading up to the Russian Revolution of 1917 and then on into the Stalinist era of the Soviet Union through an animal fable.'),
(127, 'The Great Gatsby', 'দ্য গ্রেট গ্যাটসবি', 'The Quintessential Novel of the Jazz Age', '0743273567', '9780743273565', 29, 2004, 'Trade Paperback', 'English', 'Tells the tragic story of Jay Gatsby, a self-made millionaire, and his pursuit of Daisy Buchanan, a wealthy young woman whom he loved in his youth.'),
(128, 'To Kill a Mockingbird', 'টু কিল আ মকিংবার্ড', 'A Gripping, Heart-Wrenching Tale of Racial Injustice', '0061120081', '9780061120084', 53, 2006, '50th Anniversary Edition', 'English', 'Explores the roots of human behavior—innocence and experience, kindness and cruelty, love and hatred—through young Scout Finch and her father Atticus.'),
(129, 'The Catcher in the Rye', 'দ্য ক্যাচার ইন দ্য রাই', 'Classic Coming-of-Age Story', '0316769487', '9780316769488', 54, 2001, 'Back Bay Paperback', 'English', 'Details two days in the life of 16-year-old Holden Caulfield after he has been expelled from prep school, dealing with angst and alienation.'),
(130, 'The Hobbit', 'দ্য হবিট', 'Or There and Back Again', '054792822X', '9780547928227', 55, 2012, '75th Anniversary Edition', 'English', 'Bilbo Baggins is swept into an epic quest to reclaim the lost Dwarf Kingdom of Erebor from the fearsome dragon Smaug.'),
(131, 'The Fellowship of the Ring', 'দ্য ফেলোশিপ অব দ্য রিং', 'Being the First Part of The Lord of the Rings', '0547928211', '9780547928210', 56, 2012, 'Mariner Books Edition', 'English', 'Frodo Baggins and the Fellowship embark on a perilous journey across Middle-earth to destroy the One Ring in the fires of Mount Doom.'),
(132, 'Harry Potter and the Sorcerer''s Stone', 'হ্যারি পটার অ্যান্ড দ্য সর্সারার্স স্টোন', 'US Scholastic Edition Book 1', '059035342X', '9780590353427', 57, 1998, '1st US Paperback', 'English', 'Rescued from the outrageous neglect of his aunt and uncle, a young boy with a great destiny proves his worth while attending Hogwarts.'),
(133, 'The Little Prince', 'দ্য লিটল প্রিন্স', 'A Poetic Tale of Loneliness and Friendship', '0156012197', '9780156012195', 58, 2000, 'Howard Translation', 'English', 'A pilot stranded in the desert awakes one morning to see the most extraordinary little fellow who has fallen to Earth from a tiny asteroid.'),
(134, 'One Hundred Years of Solitude', 'নিঃসঙ্গতার একশ বছর', 'The Rise and Fall of Macondo', '0060883286', '9780060883287', 53, 2006, 'Modern Classics Edition', 'English', 'Tells the multi-generational story of the Buendía family, whose patriarch, José Arcadio Buendía, founded the mythical town of Macondo.'),
(135, 'The Alchemist', 'দ্য আলকেমিস্ট', 'Special Collector''s Edition', '0062315005-2', '9780062315007-2', 17, 2014, 'Trade Paperback', 'English', 'Inspiring tale of self-discovery about listening to our hearts, recognizing opportunity, and learning to read the omens strewn along life''s path.'),
(136, 'Things Fall Apart', 'থিংস ফল অ্যাপার্ট', 'Classic of Modern African Literature', '0385474547', '9780385474542', 59, 1994, '1st Anchor Edition', 'English', 'Depicts pre-colonial life in the southeastern part of Nigeria and the invasion by Europeans during the late 19th century through Okonkwo''s story.'),
(137, 'The Kite Runner', 'দ্য কাইট রানার', 'Story of Friendship, Betrayal, and Redemption', '159463193X', '9781594631931', 60, 2013, '10th Anniversary Edition', 'English', 'Tells the story of Amir, a young boy from the Wazir Akbar Khan district of Kabul, and his close friend Hassan against the backdrop of Afghanistan''s turmoil.'),
(138, 'Life of Pi', 'লাইফ অব পাই', 'An Inspiring Adventure of Survival and Faith', '0156027321', '9780156027328', 61, 2003, '1st Mariner Edition', 'English', 'Piscine Molitor "Pi" Patel, an Indian boy from Pondicherry, survives 227 days after a shipwreck while stranded on a lifeboat in the Pacific Ocean with a Bengal tiger.'),
(139, 'The Book Thief', 'দ্য বুক থিফ', 'A Story of Words and Survival in Nazi Germany', '0375842209', '9780375842207', 62, 2007, 'Reprint Edition', 'English', 'Narrated by Death, it tells the story of Liesel Meminger, a young foster girl living outside of Munich in Nazi Germany who steals books and shares them.'),
(140, 'The Handmaid''s Tale', 'দ্য হ্যান্ডমেইডস টেল', 'A Chilling Dystopian Vision', '038549081X', '9780385490818', 59, 1998, '1st Anchor Edition', 'English', 'Set in a near-future New England, in a patriarchal, totalitarian theonomic state known as the Republic of Gilead, following the handmaid Offred.'),
(141, 'The Road', 'দ্য রোড', 'A Post-Apocalyptic Journey of Father and Son', '0307277925', '9780307277923', 50, 2006, 'Movie Tie-in Edition', 'English', 'A father and his young son walk alone through burned America, heading toward the coast across a landscape of total devastation.'),
(142, 'Midnight''s Children', 'মিডনাইটস চিলড্রেন', 'Allegory of Modern Indian History', '0812976533', '9780812976533', 41, 2006, 'Trade Paperback', 'English', 'Saleem Sinai, born at the exact stroke of midnight on August 15, 1947, finds his telepathic powers and destiny inextricably linked to his nation''s history.'),
(143, 'The God of Small Things', 'দ্য গড অব স্মল থিংস', 'Story of Forbidden Love and Childhood Tragedy', '0679457313', '9780679457312', 41, 1997, '1st Edition', 'English', 'Story about the childhood experiences of fraternal twins Rahel and Estha in Kerala, India, whose lives are destroyed by the "Love Laws".'),
(144, 'Norwegian Wood', 'নরওয়েজিয়ান উড', 'A Nostalgic Story of Loss and Sexuality', '0375704027', '9780375704024', 63, 2000, 'Rubin Translation', 'English', 'Toru Watanabe looks back on his days as a college student in Tokyo in the late 1960s and his relationships with two very different women, Naoko and Midori.'),
(145, 'Siddhartha', 'সিদ্ধার্থ', 'An Indian Novel of Spiritual Discovery', '081120068X', '9780811200684', 64, 1951, 'Rosner Translation', 'English', 'Deals with the spiritual journey of self-discovery of a man named Siddhartha during the time of the Gautama Buddha.'),
(146, 'Gitanjali', 'গীতাঞ্জলি', 'Song Offerings', '8175220007', '9788175220003', 65, 1910, 'Centenary Edition', 'Bangla', 'বিশ্বকবি রবীন্দ্রনাথ ঠাকুরের নোবেলজয়ী আধ্যাত্মিক ও ভক্তিমূলক কাব্যগ্রন্থ, যেখানে স্রষ্টা ও সৃষ্টির চিরন্তন মিলনাকুতি প্রকাশ পেয়েছে।'),
(147, 'Gora', 'গোরা', 'স্বদেশচেতনা ও মানবধর্মের উপন্যাস', '8175221127', '9788175221123', 65, 1910, 'Reprint Edition', 'Bangla', 'উনিশ শতকের শেষভাগের কোলকাতার ব্রাহ্ম ও হিন্দু সমাজের দ্বন্দ্ব, স্বদেশপ্রেম এবং অসাম্প্রদায়িক ভারতবর্ষের চেতনা নিয়ে রচিত মহাকাব্যিক উপন্যাস।'),
(148, 'Chokher Bali', 'চোখের বালি', 'বাংলা সাহিত্যের প্রথম মনস্তাত্ত্বিক উপন্যাস', '8175221453', '9788175221451', 65, 1903, 'Classic Edition', 'Bangla', 'বিনোদিনী, মহেন্দ্র, আশালতা ও বিহারীর পারস্পরিক সম্পর্ক ও মানব মনের সূক্ষ্ম টানাপোড়েন নিয়ে রচিত মনস্তাত্ত্বিক উপন্যাস।'),
(149, 'Pather Panchali', 'পথের পাঁচালী', 'অপুর সংসারের পূর্বকথা', '8179550117', '9788179550113', 66, 1929, 'Special Edition', 'Bangla', 'নিশ্চিন্তপুর গ্রামের হরিহর-সর্বজয়ার সংসার এবং অপু ও দুর্গার শৈশবের প্রকৃতিলগ্ন জীবনচিত্র।'),
(150, 'Devdas', 'দেবদাস', 'চিরন্তন ট্র্যাজিক প্রেমের উপাখ্যান', '8170790220', '9788170790228', 67, 1917, 'Classic Reprint', 'Bangla', 'দেবদাস, পার্বতী ও চন্দ্রমুখীর অমর ও বিয়োগান্তক প্রণয়কাহিনী।'),
(151, 'Srikanta', 'শ্রীকান্ত', 'চার পর্বে সম্পূর্ণ আত্মজৈবনিক উপন্যাস', '817079045X', '9788170790457', 67, 1933, 'Omnibus Edition', 'Bangla', 'ভবঘুরে শ্রীকান্তের ভ্রমণ, ইন্দ্রনাথ ও রাজলক্ষ্মীর সান্নিধ্য এবং তৎকালীন সমাজবাস্তবতার কালজয়ী উপন্যাস।'),
(152, 'Agnibina', 'অগ্নিবীণা', 'বিদ্রোহ ও জাগরণের কাব্যগ্রন্থ', '9840751239', '9789840751234', 14, 1922, 'Centenary Edition', 'Bangla', 'বিদ্রোহী, প্রলয়োল্লাস ও কামাল পাশা কবিতাসহ ব্রিটিশ বিরোধী আন্দোলন ও মানবমুক্তির অমর কাব্যগ্রন্থ।'),
(153, 'Bisher Bashi', 'বিষের বাঁশী', 'সাম্রাজ্যবাদ বিরোধী কবিতা সংকলন', '9840751247', '9789840751241', 14, 1924, 'Reprint Edition', 'Bangla', 'পরাধীনতার শৃঙ্খল ভাঙার গান ও বিদ্রোহী চেতনার কারণে ব্রিটিশ সরকার কর্তৃক বাজেয়াপ্ত হওয়া ঐতিহাসিক কাব্যগ্রন্থ।');

INSERT INTO books (id, title_en, title_bn, subtitle, isbn_10, isbn_13, publisher_id, publication_year, edition, language, description) VALUES
(154, 'Lalsalu', 'লালশালু', 'গ্রামীণ সমাজ ও বিশ্বাসের সংকট', '9849011229-2', '9789849011222-2', 68, 1948, 'Classic Edition', 'Bangla', 'মহব্বতনগর গ্রামে মজিদের আগমন ও লালশালু ঢাকা মাজারকে কেন্দ্র করে গড়ে ওঠা আধিপত্যের আখ্যান।'),
(155, 'Hajar Bachhor Dhore', 'হাজার বছর ধরে', 'আবহমান বাংলার পল্লীজীবনের উপন্যাস', '9844580129', '9789844580121', 69, 1964, '8th Edition', 'Bangla', 'টুনি ও মন্তুর অব্যক্ত প্রেম এবং গ্রামীণ বাংলার হাজার বছরের ঐতিহ্য, সংস্কার ও জীবনসংগ্রামের উপন্যাস।'),
(156, 'Ekattorer Dinguli', 'একাত্তরের দিনগুলি', 'মুক্তিযুদ্ধের প্রামাণ্য স্মৃতিকথা', '9844580455', '9789844580459', 70, 1986, '15th Edition', 'Bangla', '১৯৭১ সালের ১ মার্চ থেকে ১৭ ডিসেম্বর পর্যন্ত লেখিকার পরিবার ও বাংলাদেশের মুক্তিসংগ্রামের রক্তঝরা দিনলিপি।'),
(157, 'Ami Birangona Bolchi', 'আমি বীরাঙ্গনা বলছি', 'একাত্তরের বীরাঙ্গনাদের জীবনকথা', '9844580897', '9789844580893', 71, 1994, '6th Edition', 'Bangla', 'মহান মুক্তিযুদ্ধে নির্যাতিত নারীদের আত্মত্যাগ, বেদনা ও যুদ্ধ-পরবর্তী জীবনসংগ্রামের প্রামাণ্য দলিল।'),
(158, 'Nondito Noroke', 'নন্দিত নরকে', 'সংগ্রামী মধ্যবিত্ত জীবনের আখ্যান', '9848680011-2', '9789848680012-2', 12, 1972, 'Collector''s Edition', 'Bangla', 'রাবেয়া, খোকা ও মন্টুদের ঘিরে ঢাকার এক সাধারণ মধ্যবিত্ত পরিবারের কান্না-হাসির কালজয়ী উপন্যাস।'),
(159, 'Shonkhonil Karagar', 'শঙ্খনীল কারাগার', 'পারিবারিক মায়া ও বেদনার উপন্যাস', '984868002X', '9789848680029', 12, 1973, '12th Edition', 'Bangla', 'ভাই-বোনের অকৃত্রিম ভালোবাসা ও পারিবারিক গোপন বেদনার এক হৃদয়গ্রাহী উপাখ্যান।'),
(160, 'Jochona O Jononir Golpo', 'জোছনা ও জননীর গল্প', 'অখণ্ড সংস্করণ', '9848682227-2', '9789848682221-2', 12, 2004, 'Hardcover Edition', 'Bangla', 'মুক্তিযুদ্ধের নয় মাসের ভয়াবহতা, সাধারণ মানুষের আশ্রয়ের খোঁজ এবং বীর মুক্তিযোদ্ধাদের বীরত্বগাথা।'),
(161, 'Deyal', 'দেয়াল', 'ইতিহাস আশ্রিত রাজনৈতিক উপন্যাস', '9845021115', '9789845021111', 12, 2013, '5th Edition', 'Bangla', 'পঁচাত্তরের বিয়োগান্তক ঘটনা ও তৎপরবর্তী বাংলাদেশের রাজনৈতিক পটপরিবর্তন নিয়ে হুমায়ূন আহমেদের শেষ উপন্যাস।'),
(162, 'Dipu Number Two', 'দীপু নাম্বার টু', 'কিশোর ক্লাসিক সংস্করণ', '9848683444-2', '9789848683440-2', 72, 1984, '10th Edition', 'Bangla', 'কিশোর সাহিত্যের অন্যতম জনপ্রিয় উপন্যাস যা বন্ধুত্ব, দেশপ্রেম ও মায়ের প্রতি ভালোবাসার গল্প বলে।'),
(163, 'Amar Bondhu Rashed', 'আমার বন্ধু রাশেদ', 'কিশোর মুক্তিযোদ্ধার কাহিনী', '9848683330-2', '9789848683334-2', 72, 1994, '9th Edition', 'Bangla', 'মফস্বল শহরের একদল কিশোর কীভাবে মুক্তিযুদ্ধের বাস্তবতায় জড়িয়ে পড়ে তার অবিস্মরণীয় আখ্যান।'),
(164, 'Tuntunir Boi', 'টুনটুনির বই', 'চিরায়ত রূপকথা ও উপকথা', '8179551237', '9788179551233', 73, 1910, 'Illustrated Edition', 'Bangla', 'চালাক টুনটুনি পাখি, বোকা বাঘ ও নাপিতের মজার সব লোককাহিনী নিয়ে শিশুসাহিত্যের অমর সৃষ্টি।'),
(165, 'The Discovery of India', 'দ্য ডিসকভারি অব ইন্ডিয়া', 'A Panorama of Indian History and Culture', '0143031031', '9780143031031', 74, 2004, 'Centenary Edition', 'English', 'Written during Nehru''s imprisonment at Ahmednagar fort, tracing India''s rich history from the Indus Valley Civilization to the British Raj.'),
(166, 'The Story of My Experiments with Truth', 'আমার সত্য অন্বেষণের কাহিনী', 'An Autobiography', '817229008X', '9788172290085', 75, 1927, 'Reprint Edition', 'English', 'Covers the life of Mahatma Gandhi from early childhood through to 1921, detailing his spiritual and political experiments.'),
(167, 'Train to Pakistan', 'ট্রেন টু পাকিস্তান', 'Classic Novel of the 1947 Partition', '0143065882', '9780143065883', 74, 2009, 'Collector''s Edition', 'English', 'Recounts the Partition of India in August 1947 through the perspective of Mano Majra, a fictional border village where Sikhs and Muslims lived in peace.'),
(168, 'A Suitable Boy', 'আ সুইটেবল বয়', 'A Sweeping Panorama of Post-Independence India', '0060786523', '9780060786526', 76, 2005, 'Unabridged Edition', 'English', 'Follows four families over eighteen months in post-partition India, centering on Mrs. Rupa Mehra''s efforts to arrange the marriage of her younger daughter, Lata.'),
(169, 'The White Tiger', 'দ্য হোয়াইট টাইগার', 'A Darkly Humorous Perspective on Globalization', '1416562605', '9781416562603', 21, 2008, '1st Paperback', 'English', 'Balram Halwai writes a series of letters to the Chinese Premier explaining his rise from a village tea-shop worker to a successful entrepreneur in Bangalore.'),
(170, 'The Namesake', 'দ্য নেমসেক', 'Story of Cultural Identity and the Immigrant Experience', '0618485228', '9780618485222', 61, 2004, '1st Mariner Edition', 'English', 'Moves between events in Calcutta, Boston, and New York City, examining the nuances involved with the Ganguli family caught between two conflicting cultures.'),
(171, 'The Inheritance of Loss', 'দ্য ইনহেরিট্যান্স অব লস', 'Colonial Legacy and Modern Disillusionment', '0802142818', '9780802142818', 77, 2006, 'Paperback Edition', 'English', 'Follows the lives of Biju, an undocumented Indian immigrant in the US, and Sai, an Anglicized Indian girl living with her grandfather in Kalimpong.'),
(172, 'The Home and the World', 'ঘরে বাইরে', 'Nationalism, Tradition, and Emancipation', '0140449868', '9780140449860', 27, 2005, 'Translated Edition', 'English', 'Illustrates the battle Rabindranath Tagore had with himself, between the ideas of Western culture and revolution against the Western culture during the Swadeshi movement.'),
(173, 'I Am Malala', 'আই অ্যাম মালালা', 'The Girl Who Stood Up for Education', '0316322423', '9780316322423', 54, 2015, 'Paperback Edition', 'English', 'Remarkable tale of a family uprooted by global terrorism and the fight for girls'' education in Pakistan''s Swat Valley.'),
(174, 'Sapiens', 'স্যাপিয়েন্স', 'Collector''s Perennial Edition', '0062316095-2', '9780062316097-2', 53, 2015, 'Perennial Edition', 'English', 'Spans the whole of human history, from the very first humans to walk the earth to the radical breakthroughs of the Cognitive, Agricultural, and Scientific Revolutions.'),
(175, 'Homo Deus', 'হোমো ডিউস', 'Exploring the Projects, Dreams and Nightmares of the 21st Century', '0062464310-2', '9780062464316-2', 39, 2017, 'Paperback Edition', 'English', 'Explores the future of humanity as we seek to upgrade humans into gods through bioengineering, cyborg engineering, and non-organic life.'),
(176, 'A Brief History of Time', 'আ ব্রিফ হিস্ট্রি অব টাইম', 'Updated and Expanded Tenth Anniversary Edition', '0553380168-2', '9780553380163-2', 78, 1998, 'Expanded Edition', 'English', 'Explores profound questions such as how the universe began, whether time always flows forward, and whether the universe is infinite.'),
(177, 'Cosmos', 'কসমস', 'Story of Cosmic Evolution, Science and Civilisation', '0345539435-2', '9780345539434-2', 41, 2013, 'Trade Paperback', 'English', 'Explores the mutual development of science and civilization, astronomical missions, and the possibility of extraterrestrial life.'),
(178, 'Silent Spring', 'সাইলেন্ট স্প্রিং', 'The Classic That Launched the Environmental Movement', '0618249060', '9780618249060', 56, 2002, '40th Anniversary Edition', 'English', 'Documents the adverse environmental effects caused by the indiscriminate use of pesticides, spurring a reversal in national pesticide policy.'),
(179, 'The Selfish Gene', 'দ্য সেলফিশ জিন', '30th Anniversary Edition with a New Introduction', '0199291152', '9780199291151', 47, 2006, '30th Anniversary Edition', 'English', 'Classic exposition of evolutionary thought introducing the concept of memes and the gene as the principal unit of selection.'),
(180, 'On the Origin of Species', 'অন দ্য অরিজিন অব স্পিসিস', 'By Means of Natural Selection', '0140439129', '9780140439120', 27, 2009, '150th Anniversary Edition', 'English', 'Foundation of evolutionary biology introducing the scientific theory that populations evolve over the course of generations through natural selection.'),
(181, 'The Double Helix', 'দ্য ডাবল হেলিক্স', 'A Personal Account of the Discovery of the Structure of DNA', '074321630X', '9780743216302', 79, 2001, 'Touchstone Edition', 'English', 'Firsthand account of the race to discover the structure of DNA by James Watson and Francis Crick in Cambridge.'),
(182, 'A Short History of Nearly Everything', 'আ শর্ট হিস্ট্রি অব নিয়ারলি এভরিথিং', 'Journey Through Time and Space', '076790818X', '9780767908184', 80, 2004, 'Illustrated Edition', 'English', 'Explains some of the most complex areas of science in a conversational way, from the Big Bang to the rise of civilization.'),
(183, 'The Gene: An Intimate History', 'দ্য জিন: অ্যান ইন্টিমেট হিস্ট্রি', 'Story of the Code of Life', '147673352X', '9781476733524', 29, 2017, 'Reprint Edition', 'English', 'Weaves science, social history, and personal narrative to tell us the story of one of the most important conceptual breakthroughs of modern times.'),
(184, 'The Emperor of All Maladies', 'দ্য এম্পেরর অব অল ম্যালাডিস', 'A Biography of Cancer', '1439170916', '9781439170915', 29, 2011, 'Pulitzer Prize Edition', 'English', 'A magnificent, deeply humane biography of cancer—from its first documented appearances thousands of years ago to modern battles to cure it.'),
(185, 'The Sixth Extinction', 'দ্য সিক্সথ এক্সটিংকশন', 'An Unnatural History', '1250062187', '9781250062185', 81, 2015, 'Picador Edition', 'English', 'Explores how human activity is reshaping the biosphere and causing the sixth mass extinction event in Earth''s history.'),
(186, 'Man''s Search for Meaning', 'ম্যানস সার্চ ফর মিনিং', 'The Classic Tribute to Hope from the Holocaust', '0807014273', '9780807014271', 82, 2006, 'Revised Edition', 'English', 'Psychiatrist Viktor Frankl''s memoir of life in Nazi death camps and its lessons for spiritual survival through finding purpose in suffering.'),
(187, 'The Diary of a Young Girl', 'আনা ফ্রাঙ্কের ডায়েরি', 'The Definitive Edition', '0553296981', '9780553296983', 78, 1993, 'Mass Market Edition', 'English', 'Discovered in the attic in which she spent the last years of her life, Anne Frank''s remarkable diary has become a world classic of wartime testimony.'),
(188, 'Long Walk to Freedom', 'লং ওয়াক টু ফ্রিডম', 'The Autobiography of Nelson Mandela', '0316548189', '9780316548182', 83, 1995, '1st Paperback', 'English', 'Profiles the life of South African President Nelson Mandela, covering his early life, education, 27 years in prison, and the end of apartheid.'),
(189, 'How to Win Friends and Influence People', 'হাউ টু উইন ফ্রেন্ডস অ্যান্ড ইনফ্লুয়েন্স পিপল', 'Pocket Books Classic Edition', '0671027034-2', '9780671027032', 84, 1998, 'Mass Market Edition', 'English', 'Classic manual on human relations teaching six ways to make people like you and twelve ways to win people to your way of thinking.'),
(190, 'Atomic Habits', 'অ্যাটমিক হ্যাবিটস', 'International Paperback Edition', '0735211299-2', '9780735211292-2', 19, 2018, 'International Edition', 'English', 'Practical strategies that will teach you exactly how to form good habits, break bad ones, and master the tiny behaviors that lead to remarkable results.'),
(191, 'Clean Code', 'ক্লিন কোড', 'Agile Software Craftsmanship Reference', '0132350882-2', '9780132350884-2', 33, 2008, '1st Edition', 'English', 'Divided into three parts: the principles, patterns, and practices of writing clean code; case studies of increasing complexity; and heuristics.'),
(192, 'The Pragmatic Programmer', 'দ্য প্র্যাগম্যাটিক প্রোগ্রামার', 'From Journeyman to Master', '0135957052-2', '9780135957059-2', 35, 2019, '2nd Edition', 'English', 'Illustrates the best approaches and major pitfalls of many different aspects of software development for modern engineers.'),
(193, 'Design Patterns', 'ডিজাইন প্যাটার্নস', 'Reusable Object-Oriented Software Architecture', '0201633612-2', '9780201633610-2', 85, 1994, 'Hardcover Edition', 'English', 'Describes simple and elegant solutions to specific problems in object-oriented software design, naming and explaining 23 key patterns.'),
(194, 'Code Complete', 'কোড কমপ্লিট', 'A Practical Handbook of Software Construction', '0735619670', '9780735619678', 86, 2004, '2nd Edition', 'English', 'Synthesizes the most effective techniques and must-know principles into clear, pragmatic guidance for software construction.'),
(195, 'Introduction to Algorithms', 'ইন্ট্রোডাকশন টু অ্যালগরিদমস', 'Fourth Edition CLRS', '026204630X', '9780262046305', 32, 2022, '4th Edition', 'English', 'Updated fourth edition featuring new chapters on matchings in bipartite graphs, online algorithms, and machine learning algorithms.'),
(196, 'Computer Networking: A Top-Down Approach', 'কম্পিউটার নেটওয়ার্কিং: আ টপ-ডাউন অ্যাপ্রোচ', 'Internet and Protocol Stack Architecture', '0136681557', '9780136681557', 87, 2020, '8th Edition', 'English', 'Teaches computer networking by starting at the application layer and working down toward the physical layer of the protocol stack.'),
(197, 'Operating Systems: Three Easy Pieces', 'অপারেটিং সিস্টেমস: থ্রি ইজি পিসেস', 'Virtualization, Concurrency, and Persistence', '198508659X', '9781985086593', 88, 2018, 'Version 1.00', 'English', 'Centered around three conceptual pieces that are fundamental to operating systems: virtualization, concurrency, and persistence.'),
(198, 'Artificial Intelligence: A Modern Approach', 'আর্টিফিশিয়াল ইন্টেলিজেন্স: আ মডার্ন অ্যাপ্রোচ', 'Comprehensive Guide to AI Theory and Practice', '0134610997', '9780134610993', 87, 2020, '4th Edition', 'English', 'Offers the most comprehensive, up-to-date introduction to the theory and practice of artificial intelligence, deep learning, and robotics.'),
(199, 'Structure and Interpretation of Computer Programs', 'স্ট্রাকচার অ্যান্ড ইন্টারপ্রিটেশন অব কম্পিউটার প্রোগ্রামস', 'The Wizard Book (SICP)', '0262510871', '9780262510875', 32, 1996, '2nd Edition', 'English', 'Teaches fundamental principles of computer programming, including recursion, abstraction, modularity, and programming language design.'),
(200, 'The C Programming Language', 'দ্য সি প্রোগ্রামিং ল্যাঙ্গুয়েজ', 'ANSI C Edition (K&R)', '0131103628', '9780131103627', 33, 1988, '2nd Edition', 'English', 'Authoritative reference manual and tutorial for the C programming language written by its original co-creators at Bell Labs.'),
(201, 'C Programming: A Modern Approach', 'সি প্রোগ্রামিং: আ মডার্ন অ্যাপ্রোচ', 'C89 and C99 Standard Reference (CSE 111)', '0393979504', '9780393979503', 89, 2008, '2nd Edition', 'English', 'Comprehensive textbook on structured programming in C covering C89 and C99 standards, pointers, memory management, and standard libraries.'),
(202, 'Programming in C', 'প্রোগ্রামিং ইন সি', 'A Complete Introduction to the C Language (CSE 111)', '0321776410', '9780321776419', 87, 2014, '4th Edition', 'English', 'Teaches how to write programs in the C language with step-by-step examples, covering fundamentals, data types, and file input/output.'),
(203, 'C++ Primer', 'সি++ প্রাইমার', 'Comprehensive Introduction to Modern C++ (CSE 121)', '0321714113', '9780321714114', 85, 2012, '5th Edition', 'English', 'Authoritative introduction to C++11 covering object-oriented programming, generic programming, and the C++ standard library.');

INSERT INTO books (id, title_en, title_bn, subtitle, isbn_10, isbn_13, publisher_id, publication_year, edition, language, description) VALUES
(204, 'Programming: Principles and Practice Using C++', 'প্রোগ্রামিং: প্রিন্সিপলস অ্যান্ড প্র্যাকটিস ইউজিং সি++', 'Introduction to Programming by the Creator of C++ (CSE 121)', '0321992784', '9780321992789', 85, 2014, '2nd Edition', 'English', 'Introduces fundamental programming concepts, object-oriented design, and generic programming using C++11 and C++14.'),
(205, 'Effective Modern C++', 'ইফেক্টিভ মডার্ন সি++', '42 Specific Ways to Improve Your Use of C++11 and C++14', '1491903996', '9781491903995', 34, 2014, '1st Edition', 'English', 'Practical guidelines for mastering modern C++ features including auto type declarations, move semantics, lambda expressions, and smart pointers.'),
(206, 'The C++ Programming Language', 'দ্য সি++ প্রোগ্রামিং ল্যাঙ্গুয়েজ', 'Definitive Reference to C++ (CSE 331)', '0321563840', '9780321563842', 85, 2013, '4th Edition', 'English', 'Complete and exhaustive reference to the C++ language and standard library written by its original designer.'),
(207, 'Core Java, Volume I—Fundamentals', 'কোর জাভা, ভলিউম ১—ফান্ডামেন্টালস', 'Guide to Java Platform Standard Edition', '0137673620', '9780137673629', 87, 2021, '12th Edition', 'English', 'Detailed guide for serious programmers covering core Java language features, object-oriented design, generics, collections, and lambda expressions.'),
(208, 'Java Concurrency in Practice', 'জাভা কনকারেন্সি ইন প্র্যাকটিস', 'Thread Safety, Locks, and Parallelism', '0321349601', '9780321349606', 85, 2006, '1st Edition', 'English', 'Essential handbook on developing concurrent and multithreaded programs in Java, covering thread safety, task execution, and performance.'),
(209, 'Modern Java in Action', 'মডার্ন জাভা ইন অ্যাকশন', 'Lambdas, Streams, Functional and Reactive Programming', '1617293563', '9781617293566', 90, 2018, '1st Edition', 'English', 'Explores modern Java features including functional programming, streams API, CompletableFuture, and reactive programming techniques.'),
(210, 'Fluent Python', 'ফ্লুয়েন্ট পাইথন', 'Clear, Concise, and Effective Programming', '1492056359', '9781492056355', 34, 2022, '2nd Edition', 'English', 'Deep dive into Python''s core data model, data structures, functions as objects, object-oriented idioms, and metaprogramming.'),
(211, 'Learning Python', 'লার্নিং পাইথন', 'Powerful Object-Oriented Programming', '1449355730', '9781449355739', 34, 2013, '5th Edition', 'English', 'Comprehensive, in-depth introduction to the core Python language, types, statements, functions, modules, and classes.'),
(212, 'Think Python', 'থিংক পাইথন', 'How to Think Like a Computer Scientist', '1491939362', '9781491939369', 34, 2015, '2nd Edition', 'English', 'Concise introduction to software design and programming fundamentals using the Python language for beginners.'),
(213, 'Data Structures and Algorithm Analysis in C++', 'ডেটা স্ট্রাকচারস অ্যান্ড অ্যালগরিদম অ্যানালাইসিস ইন সি++', 'Modern C++ Approach to Data Structures (CSE 231)', '013284737X', '9780132847377', 87, 2013, '4th Edition', 'English', 'Examines algorithm analysis, trees, hashing, priority queues, sorting, graph algorithms, and amortized analysis in C++.'),
(214, 'Algorithms', 'অ্যালগরিদমস', 'Essential Information About Algorithms and Data Structures (CSE 241)', '032157351X', '9780321573513', 85, 2011, '4th Edition', 'English', 'Surveys the most important computer algorithms in use today, covering sorting, searching, graph processing, and string processing.'),
(215, 'Algorithm Design', 'অ্যালগরিদম ডিজাইন', 'Design and Analysis of Computer Algorithms (CSE 241)', '0321295358', '9780321295354', 87, 2005, '1st Edition', 'English', 'Introduces algorithmic design patterns including greedy algorithms, divide and conquer, dynamic programming, network flow, and NP-completeness.'),
(216, 'Data Structures and Algorithms in Java', 'ডেটা স্ট্রাকচারস অ্যান্ড অ্যালগরিদমস ইন জাভা', 'Comprehensive Object-Oriented Data Structures', '1118771338', '9781118771334', 91, 2014, '6th Edition', 'English', 'Offers clear design and analysis of data structures and algorithms using the Java programming language.'),
(217, 'Competitive Programming 4, Volume 1', 'কম্পিটিটিভ প্রোগ্রামিং ৪, ১ম খণ্ড', 'The Lower Bound of Programming Contests in the 2020s', '1716745519', '9781716745515', 92, 2020, '4th Edition', 'English', 'Prepares students for ICPC and IOI programming contests covering ad-hoc problems, linear data structures, and complete search techniques.'),
(218, 'Competitive Programming 4, Volume 2', 'কম্পিটিটিভ প্রোগ্রামিং ৪, ২য় খণ্ড', 'Advanced Algorithms for ICPC Contests', '1716745527', '9781716745522', 92, 2020, '4th Edition', 'English', 'Covers advanced graph algorithms, computational geometry, string processing, and mathematics for competitive programmers.'),
(219, 'Discrete Mathematics and Its Applications', 'ডিসক্রিট ম্যাথমেটিকস অ্যান্ড ইটস অ্যাপ্লিকেশনস', 'Foundations of Logic, Sets, and Combinatorics (CSE 103)', '125967651X', '9781259676512', 93, 2018, '8th Edition', 'English', 'Industry-standard textbook covering mathematical reasoning, combinatorial analysis, discrete structures, and algorithmic thinking.'),
(220, 'Discrete Mathematics with Applications', 'ডিসক্রিট ম্যাথমেটিকস উইথ অ্যাপ্লিকেশনস', 'Clear Introduction to Mathematical Reasoning (CSE 103)', '1337694193', '9781337694193', 94, 2019, '5th Edition', 'English', 'Explains complex, abstract concepts of logic, proof techniques, number theory, recursion, and graphs with clarity and precision.'),
(221, 'Concrete Mathematics', 'কনক্রিট ম্যাথমেটিকস', 'A Foundation for Computer Science (CSE 313)', '0201558025', '9780201558029', 35, 1994, '2nd Edition', 'English', 'Blends continuous and discrete mathematics, covering sums, recurrences, integer functions, binomial coefficients, and asymptotics.'),
(222, 'Graph Theory', 'গ্রাফ থিওরি', 'Graduate Texts in Mathematics (CSE 469)', '3662536218', '9783662536216', 95, 2017, '5th Edition', 'English', 'Rigorous mathematical treatment of modern graph theory including matchings, connectivity, planarity, coloring, flows, and Ramsey theory.'),
(223, 'Calculus: Early Transcendentals', 'ক্যালকুলাস: আর্লি ট্রান্সসেন্ডেন্টালস', 'Differential and Integral Calculus (MAT 101)', '1337613924', '9781337613927', 94, 2020, '9th Edition', 'English', 'Renowned for its mathematical precision, patient explanations, and problem sets covering limits, derivatives, integrals, and infinite series.'),
(224, 'Introduction to Linear Algebra', 'ইন্ট্রোডাকশন টু লিনিয়ার অ্যালজেব্রা', 'Vectors, Matrices, and Vector Spaces (MAT 121)', '0980232775', '9780980232776', 96, 2016, '5th Edition', 'English', 'Fundamental textbook on linear algebra covering Gaussian elimination, subspaces, orthogonality, eigenvalues, and singular value decomposition.'),
(225, 'Elementary Differential Equations and Boundary Value Problems', 'এলিমেন্টারি ডিফারেনশিয়াল ইকুয়েশনস অ্যান্ড বাউন্ডারি ভ্যালু প্রবলেমস', 'Ordinary and Partial Differential Equations (MAT 121)', '1119820642', '9781119820647', 91, 2021, '12th Edition', 'English', 'Classic engineering mathematics text covering first-order and higher-order differential equations, Laplace transforms, and Fourier series.'),
(226, 'Complex Variables and Applications', 'কমপ্লেক্স ভ্যারিয়েবলস অ্যান্ড অ্যাপ্লিকেশনস', 'Analytic Functions, Residues, and Conformal Mapping (MAT 231)', '0073383171', '9780073383170', 5, 2013, '9th Edition', 'English', 'Comprehensive introduction to complex analysis, contour integration, Cauchy''s theorem, residue calculus, and harmonic functions.'),
(227, 'Probability and Computing', 'প্রোবাবিলিটি অ্যান্ড কম্পিউটিং', 'Randomization and Probabilistic Techniques in Algorithms', '110715488X', '9781107154889', 97, 2017, '2nd Edition', 'English', 'Explores randomized algorithms and probabilistic analysis in computer science, including Markov chains, Chernoff bounds, and hashing.'),
(228, 'Numerical Analysis', 'নিউমেরিক্যাল অ্যানালাইসিস', 'Mathematical Theory and Approximation Methods (CSE 223)', '1305253663', '9781305253667', 94, 2015, '10th Edition', 'English', 'Introduces modern approximation techniques, numerical differentiation and integration, interpolation, and numerical linear algebra.'),
(229, 'Numerical Methods for Engineers', 'নিউমেরিক্যাল মেথডস ফর ইঞ্জিনিয়ার্স', 'Computational Problem Solving in Engineering (CSE 223)', '007339792X', '9780073397924', 93, 2014, '7th Edition', 'English', 'Presents numerical methods with a practical, problem-solving orientation for engineering and computer science students.'),
(230, 'Digital Design', 'ডিজিটাল ডিজাইন', 'With an Introduction to the Verilog HDL, VHDL, and SystemVerilog (CSE 205)', '0134549899', '9780134549897', 87, 2017, '6th Edition', 'English', 'Teaches the basic tools for the design of digital circuits, Boolean algebra, combinational logic, synchronous sequential logic, and HDLs.'),
(231, 'Digital Fundamentals', 'ডিজিটাল ফান্ডামেন্টালস', 'Logic Gates, Flip-Flops, and Microprocessor Basics', '0132737965', '9780132737968', 87, 2014, '11th Edition', 'English', 'Provides a strong foundation in core fundamentals of digital technology, troubleshooting, programmable logic, and memory systems.'),
(232, 'Fundamentals of Digital Logic with Verilog Design', 'ফান্ডামেন্টালস অব ডিজিটাল লজিক উইথ ভেরিলগ ডিজাইন', 'Logic Synthesis and FPGA Implementation', '0073380547', '9780073380544', 5, 2013, '3rd Edition', 'English', 'Teaches digital circuit design principles combined with practical hardware description using Verilog HDL.'),
(233, 'Computer Organization and Design', 'কম্পিউটার অর্গানাইজেশন অ্যান্ড ডিজাইন', 'The Hardware/Software Interface (CSE 215)', '0128201096', '9780128201091', 98, 2020, '6th Edition', 'English', 'Explores RISC/MIPS/ARM processor design, pipelining, memory hierarchy, cache coherence, and parallel hardware architecture.'),
(234, 'Structured Computer Organization', 'স্ট্রাকচার্ড কম্পিউটার অর্গানাইজেশন', 'Multilevel Machine Architecture (CSE 215)', '0132916525', '9780132916523', 87, 2012, '6th Edition', 'English', 'Explains how computers work by organizing the machine as a hierarchy of levels: digital logic, microarchitecture, ISA, OS, and assembly.'),
(235, 'Computer Architecture: A Quantitative Approach', 'কম্পিউটার আর্কিটেকচার: আ কোয়ান্টিটেটিভ অ্যাপ্রোচ', 'Advanced Processor, Memory, and Warehouse-Scale Design', '0128119055', '9780128119051', 98, 2017, '6th Edition', 'English', 'Definitive reference on instruction-level, data-level, and thread-level parallelism, domain-specific architectures, and GPU computing.'),
(236, 'Microprocessor Architecture, Programming, and Applications with the 8085', 'মাইক্রোপ্রসেসর আর্কিটেকচার, প্রোগ্রামিং অ্যান্ড অ্যাপ্লিকেশনস উইথ দ্য ৮০৮৫', 'Assembly Language and Hardware Interfacing (CSE 315)', '8173714088', '9788173714080', 99, 2013, '6th Edition', 'English', 'Comprehensive guide to the 8085 microprocessor architecture, instruction set, interrupts, counters, and peripheral interfacing ICs.'),
(237, 'Embedded Systems: Architecture, Programming and Design', 'এমবেডেড সিস্টেমস: আর্কিটেকচার, প্রোগ্রামিং অ্যান্ড ডিজাইন', 'Microcontrollers and Real-Time Operating Systems (CSE 425)', '0070667640', '9780070667648', 93, 2017, '3rd Edition', 'English', 'Covers embedded hardware, ARM/8051 microcontrollers, device drivers, communication buses, and real-time operating system design.'),
(238, 'Making Embedded Systems', 'মেকিং এমবেডেড সিস্টেমস', 'Design Patterns for Great Software (CSE 425)', '1449302149', '9781449302146', 34, 2011, '1st Edition', 'English', 'Practical guide to building reliable firmware and embedded software for resource-constrained microcontrollers and sensors.'),
(239, 'Operating System Concepts', 'অপারেটিং সিস্টেম কনসেপ্টস', 'The Dinosaur Book on OS Fundamentals (CSE 309)', '1119800366', '9781119800361', 91, 2021, '10th Edition', 'English', 'Covers fundamental OS concepts including process management, threads, CPU scheduling, synchronization, deadlocks, virtual memory, and file systems.'),
(240, 'Modern Operating Systems', 'মডার্ন অপারেটিং সিস্টেমস', 'Design Principles and Case Studies (CSE 309)', '013359162X', '9780133591620', 87, 2014, '4th Edition', 'English', 'Detailed examination of operating system theory and implementation with case studies on Linux, Android, and Windows.'),
(241, 'Operating Systems: Three Easy Pieces', 'অপারেটিং সিস্টেমস: থ্রি ইজি পিসেস', 'Virtualization, Concurrency, and Persistence (CSE 309)', '198508659X-2', '9781985086593-2', 88, 2018, '1st Edition', 'English', 'Accessible, engaging textbook breaking operating systems down into CPU/memory virtualization, multithreaded concurrency, and disk persistence.'),
(242, 'The Linux Programming Interface', 'দ্য লিনাক্স প্রোগ্রামিং ইন্টারফেস', 'A Linux and UNIX System Programming Handbook', '1593272200', '9781593272203', 36, 2010, '1st Edition', 'English', 'Definitive reference to the Linux and UNIX system call interface, covering file I/O, signals, timers, processes, IPC, and sockets.'),
(243, 'Linux Kernel Development', 'লিনাক্স কার্নেল ডেভেলপমেন্ট', 'Design and Implementation of the Linux Kernel', '0672329468', '9780672329463', 85, 2010, '3rd Edition', 'English', 'Details the major subsystems and features of the Linux 2.6 kernel, including process scheduling, system calls, interrupts, and VFS.'),
(244, 'Computer Networking: A Top-Down Approach', 'কম্পিউটার নেটওয়ার্কিং: আ টপ-ডাউন অ্যাপ্রোচ', 'Internet Architecture from Application to Physical Layer (CSE 319)', '0136681557-2', '9780136681557-2', 87, 2020, '8th Edition', 'English', 'Teaches computer networking concepts using a top-down approach starting from HTTP/DNS down to TCP/IP, routing, and wireless links.'),
(245, 'Computer Networks', 'কম্পিউটার নেটওয়ার্কস', 'Comprehensive Protocol Reference (CSE 319)', '0132126958', '9780132126953', 87, 2010, '5th Edition', 'English', 'Explains the inside-out workings of computer networks layer by layer, from physical transmission media to application protocols.'),
(246, 'Data and Computer Communications', 'ডেটা অ্যান্ড কম্পিউটার কমিউনিকেশনস', 'Signal Transmission, Multiplexing, and Switching (CSE 209)', '0133506487', '9780133506488', 87, 2013, '10th Edition', 'English', 'Covers the fundamental principles of data communication, digital/analog encoding, error detection, multiplexing, and LANs/WANs.'),
(247, 'TCP/IP Illustrated, Volume 1: The Protocols', 'টিসিপি/আইপি ইলাস্ট্রেটেড, ভলিউম ১', 'Complete Reference to the Internet Protocol Suite', '0321336313', '9780321336316', 85, 2011, '2nd Edition', 'English', 'Visual and practical guide to how the TCP/IP protocol suite works in practice, including IPv4, IPv6, DHCP, NAT, ICMP, and TCP congestion control.'),
(248, 'Network Security Essentials', 'নেটওয়ার্ক সিকিউরিটি এসেনশিয়ালস', 'Applications and Standards (CSE 455)', '013452733X', '9780134527338', 87, 2016, '6th Edition', 'English', 'Practical survey of network security applications and standards, including symmetric/public-key encryption, TLS, IPsec, and firewalls.'),
(249, 'Database System Concepts', 'ডেটাবেস সিস্টেম কনসেপ্টস', 'Relational Models, SQL, and Transaction Processing (CSE 207)', '0078022150', '9780078022159', 93, 2019, '7th Edition', 'English', 'Classic textbook covering relational algebra, SQL, E-R modeling, normalization, query optimization, ACID transactions, and recovery.'),
(250, 'Fundamentals of Database Systems', 'ফান্ডামেন্টালস অব ডেটাবেস সিস্টেমস', 'Database Design, Modeling, and Architecture (CSE 207)', '0133970779', '9780133970777', 87, 2015, '7th Edition', 'English', 'In-depth coverage of conceptual modeling, relational database design theory, SQL programming, indexing structures, and NoSQL systems.'),
(251, 'Database Management Systems', 'ডেটাবেস ম্যানেজমেন্ট সিস্টেমস', 'Cow Book on DBMS Internals (CSE 207)', '0072465638', '9780072465631', 5, 2002, '3rd Edition', 'English', 'Comprehensive foundation in database design and the implementation of database management systems, storage, and concurrency control.'),
(252, 'Designing Data-Intensive Applications', 'ডিজাইনিং ডেটা-ইনটেনসিভ অ্যাপ্লিকেশনস', 'Distributed Databases and Scalable Systems (CSE 417)', '1449373321', '9781449373320', 34, 2017, '1st Edition', 'English', 'Explores replication, partitioning, distributed transactions, consensus algorithms, batch processing, and stream processing.'),
(253, 'SQL Cookbook', 'এসকিউএল কুকবুক', 'Query Solutions and Techniques for All SQL Users (CSE 457)', '1492077445', '9781492077442', 34, 2020, '2nd Edition', 'English', 'Practical recipes for window functions, hierarchical queries, pivoting, string manipulation, and advanced SQL reporting across major RDBMSs.');

