(254, 'MySQL Cookbook', 'মাইএসকিউএল কুকবুক', 'Solutions for Database Developers and Administrators', '1492093165', '9781492093169', 34, 2022, '4th Edition', 'English', 'Problem-solving guide for MySQL 8 covering stored routines, triggers, JSON handling, replication, and database administration.'),
(255, 'Introduction to Automata Theory, Languages, and Computation', 'ইন্ট্রোডাকশন টু অটোমাটা থিওরি, ল্যাঙ্গুয়েজেস অ্যান্ড কম্পিউটেশন', 'Cinderella Book on Formal Languages (CSE 213)', '0321455363', '9780321455369', 87, 2006, '3rd Edition', 'English', 'Classic text on finite automata, regular expressions, context-free grammars, pushdown automata, Turing machines, and undecidability.'),
(256, 'Introduction to the Theory of Computation', 'ইন্ট্রোডাকশন টু দ্য থিওরি অব কম্পিউটেশন', 'Automata, Computability, and Complexity (CSE 213)', '113318779X', '9781133187790', 94, 2012, '3rd Edition', 'English', 'Renowned for its crystal-clear proofs and intuition covering automata theory, Turing decidability, time/space complexity, and P vs NP.'),
(257, 'Elements of the Theory of Computation', 'এলিমেন্টস অব দ্য থিওরি অব কম্পিউটেশন', 'Mathematical Foundations of Formal Languages', '0132624788', '9780132624787', 87, 1997, '2nd Edition', 'English', 'Rigorous presentation of sets, languages, finite automata, context-free languages, Turing machines, and computational intractability.'),
(258, 'Compilers: Principles, Techniques, and Tools', 'কম্পাইলারস: প্রিন্সিপলস, টেকনিকস অ্যান্ড টুলস', 'The Dragon Book on Compiler Construction (CSE 323)', '0321486811', '9780321486813', 87, 2006, '2nd Edition', 'English', 'Definitive textbook on lexical analysis, syntax parsing, syntax-directed translation, intermediate code generation, and code optimization.'),
(259, 'Engineering a Compiler', 'ইঞ্জিনিয়ারিং আ কম্পাইলার', 'Modern Code Optimization and Backend Design (CSE 323)', '0128154128', '9780128154120', 98, 2022, '3rd Edition', 'English', 'Focuses on practical compiler engineering, SSA form, data-flow analysis, instruction scheduling, and register allocation.'),
(260, 'Modern Compiler Implementation in C', 'মডার্ন কম্পাইলার ইমপ্লিমেন্টেশন ইন সি', 'The Tiger Book on Building a Complete Compiler (CSE 323)', '0521607655', '9780521607650', 97, 2004, 'Revised Edition', 'English', 'Explains all phases of a modern compiler with a student project implementing a compiler for the Tiger language in C.'),
(261, 'Software Engineering', 'সফটওয়্যার ইঞ্জিনিয়ারিং', 'System Dependability, Requirements, and Processes (CSE 327)', '0137035152', '9780137035151', 87, 2015, '10th Edition', 'English', 'Comprehensive introduction to software processes, agile development, requirements engineering, system modeling, and dependability.'),
(262, 'Software Engineering: A Practitioner''s Approach', 'সফটওয়্যার ইঞ্জিনিয়ারিং: আ প্র্যাকটিশনার্স অ্যাপ্রোচ', 'Software Process Models and Quality Management (CSE 327)', '1259872971', '9781259872976', 93, 2019, '9th Edition', 'English', 'Widely used textbook covering software engineering lifecycle, agile practices, architectural design, testing strategies, and metrics.'),
(263, 'UML Distilled', 'ইউএমএল ডিস্টিলড', 'A Brief Guide to the Standard Object Modeling Language (CSE 317)', '0321193687', '9780321193681', 85, 2003, '3rd Edition', 'English', 'Concise guide to Unified Modeling Language diagrams including class, sequence, use case, state machine, and activity diagrams.'),
(264, 'Domain-Driven Design', 'ডোমেইন-ড্রিভেন ডিজাইন', 'Tackling Complexity in the Heart of Software (CSE 461)', '0321125215', '9780321125217', 85, 2003, '1st Edition', 'English', 'Introduces ubiquitous language, bounded contexts, entities, value objects, aggregates, and strategic software design.'),
(265, 'Clean Architecture', 'ক্লিন আর্কিটেকচার', 'A Craftsman''s Guide to Software Structure and Design (CSE 461)', '0134494164', '9780134494166', 33, 2017, '1st Edition', 'English', 'Explains SOLID design principles, component cohesion, boundaries, and decoupled architecture for enterprise systems.'),
(266, 'Working Effectively with Legacy Code', 'ওয়ার্কিং ইফেক্টিভলি উইথ লিগ্যাসি কোড', 'Refactoring and Testing Untested Systems', '0131177052', '9780131177055', 33, 2004, '1st Edition', 'English', 'Strategies for safely modifying large, untested legacy codebases by breaking dependencies and introducing unit tests.'),
(267, 'The Art of Software Testing', 'দ্য আর্ট অব সফটওয়্যার টেস্টিং', 'Black-Box, White-Box, and Integration Testing (CSE 453)', '1118031962', '9781118031964', 91, 2011, '3rd Edition', 'English', 'Classic guide to software testing methodologies, test case design, module testing, debugging, and agile testing.'),
(268, 'Agile Software Development, Principles, Patterns, and Practices', 'অ্যাজাইল সফটওয়্যার ডেভেলপমেন্ট', 'Extreme Programming and Object-Oriented Design', '0131005685', '9780131005680', 33, 2002, '1st Edition', 'English', 'Illustrates Agile values, TDD, refactoring, OOD principles, and design patterns through practical case studies.'),
(269, 'Software Project Management', 'সফটওয়্যার প্রজেক্ট ম্যানেজমেন্ট', 'Project Planning, Estimation, and Risk Management (CSE 451)', '0077122798', '9780077122790', 93, 2009, '5th Edition', 'English', 'Covers project evaluation, effort estimation, COCOMO, activity planning, risk management, monitoring, and team organization.'),
(270, 'Artificial Intelligence: A Guide to Intelligent Systems', 'আর্টিফিশিয়াল ইন্টেলিজেন্স: আ গাইড টু ইন্টেলিজেন্ট সিস্টেমস', 'Expert Systems, Fuzzy Logic, and Neural Networks (CSE 351)', '1408225743', '9781408225745', 87, 2011, '3rd Edition', 'English', 'Accessible introduction to rule-based expert systems, uncertainty management, fuzzy logic, artificial neural networks, and evolutionary computation.'),
(271, 'Artificial Intelligence: Foundations of Computational Agents', 'আর্টিফিশিয়াল ইন্টেলিজেন্স: ফাউন্ডেশনস অব কম্পিউটেশনাল এজেন্টস', 'Agent Architecture, Search, and Planning (CSE 351)', '110719539X', '9781107195394', 97, 2017, '2nd Edition', 'English', 'Coherent framework for studying intelligent computational agents, state-space search, constraint satisfaction, logic, and planning under uncertainty.'),
(272, 'Machine Learning', 'মেশিন লার্নিং', 'Foundational Concepts in Inductive Learning (CSE 465)', '0070428077', '9780070428072', 5, 1997, '1st Edition', 'English', 'Classic textbook covering concept learning, decision trees, neural networks, Bayesian learning, computational learning theory, and reinforcement learning.'),
(273, 'Pattern Recognition and Machine Learning', 'প্যাটার্ন রিকগনিশন অ্যান্ড মেশিন লার্নিং', 'Bayesian Methods and Graphical Models (CSE 467)', '0387310738', '9780387310732', 95, 2006, '1st Edition', 'English', 'Comprehensive Bayesian treatment of linear models, kernel methods, graphical models, mixture models, EM, and approximate inference.'),
(274, 'Hands-On Machine Learning with Scikit-Learn, Keras, and TensorFlow', 'হ্যান্ডস-অন মেশিন লার্নিং', 'Concepts, Tools, and Techniques to Build Intelligent Systems (CSE 465)', '1098125975', '9781098125974', 34, 2022, '3rd Edition', 'English', 'Practical guide to building end-to-end machine learning and deep learning models using Python''s Scikit-Learn, Keras, and TensorFlow.'),
(275, 'Deep Learning', 'ডিপ লার্নিং', 'Foundations of Neural Networks and Representation Learning (CSE 477)', '0262035618', '9780262035613', 32, 2016, '1st Edition', 'English', 'Covers deep feedforward networks, regularization, optimization, CNNs, sequence modeling with RNNs, autoencoders, and generative models.'),
(276, 'The Elements of Statistical Learning', 'দ্য এলিমেন্টস অব স্ট্যাটিস্টিক্যাল লার্নিং', 'Data Mining, Inference, and Prediction', '0387848576', '9780387848570', 95, 2009, '2nd Edition', 'English', 'Mathematical treatment of supervised and unsupervised learning including shrinkage methods, splines, boosting, random forests, and SVMs.'),
(277, 'An Introduction to Statistical Learning', 'অ্যান ইন্ট্রোডাকশন টু স্ট্যাটিস্টিক্যাল লার্নিং', 'With Applications in R / Python', '1071614177', '9781071614174', 95, 2021, '2nd Edition', 'English', 'Accessible overview of statistical learning methods including regression, classification, resampling, tree-based methods, and survival analysis.'),
(278, 'Data Mining: Concepts and Techniques', 'ডেটা মাইনিং: কনসেপ্টস অ্যান্ড টেকনিকস', 'Knowledge Discovery from Large Databases (CSE 475)', '0123814790', '9780123814791', 98, 2011, '3rd Edition', 'English', 'Covers data preprocessing, data warehousing, frequent pattern mining, classification, cluster analysis, and outlier detection.'),
(279, 'Fuzzy Logic with Engineering Applications', 'ফাজি লজিক উইথ ইঞ্জিনিয়ারিং অ্যাপ্লিকেশনস', 'Fuzzy Sets, Approximate Reasoning, and Control (CSE 477)', '1119235863', '9781119235866', 91, 2016, '4th Edition', 'English', 'Practical introduction to fuzzy sets, fuzzy relations, membership functions, defuzzification, fuzzy rule-based systems, and fuzzy control.'),
(280, 'Computer Graphics: Principles and Practice', 'কম্পিউটার গ্রাফিক্স: প্রিন্সিপলস অ্যান্ড প্র্যাকটিস', '2D/3D Rendering, Geometric Modeling, and Shaders (CSE 341)', '0321399528', '9780321399526', 85, 2013, '3rd Edition', 'English', 'Comprehensive reference on 2D/3D graphics pipelines, transformations, viewing, light transport, rasterization, and ray tracing.'),
(281, 'Fundamentals of Computer Graphics', 'ফান্ডামেন্টালস অব কম্পিউটার গ্রাফিক্স', 'Mathematical Foundations of 3D Graphics (CSE 341)', '0367505037', '9780367505035', 100, 2021, '5th Edition', 'English', 'Clear introduction to ray tracing, transformation matrices, viewing, texture mapping, shading, curves, and computer animation.'),
(282, 'Real-Time Rendering', 'রিয়েল-টাইম রেন্ডারিং', 'GPU Pipelines, Shading, and Global Illumination', '0367509881', '9780367509883', 100, 2018, '4th Edition', 'English', 'Focuses on modern algorithms for creating synthetic images fast enough for interactive 3D graphics and game engines.'),
(283, 'Computer Vision: Algorithms and Applications', 'কম্পিউটার ভিশন: অ্যালগরিদমস অ্যান্ড অ্যাপ্লিকেশনস', 'Image Processing, 3D Reconstruction, and Deep Vision (CSE 487)', '3030343715', '9783030343712', 95, 2022, '2nd Edition', 'English', 'Explores image formation, feature detection, alignment, stereo correspondence, structure from motion, and deep learning for vision.'),
(284, 'Probabilistic Robotics', 'প্রোবাবিলিস্টিক রোবোটিক্স', 'Localization, Mapping, and SLAM (CSE 487)', '0262201623', '9780262201629', 32, 2005, '1st Edition', 'English', 'Introduces Kalman filters, particle filters, mobile robot localization, occupancy grid mapping, and Simultaneous Localization and Mapping (SLAM).'),
(285, 'Introduction to Robotics: Mechanics and Control', 'ইন্ট্রোডাকশন টু রোবোটিক্স: মেকানিক্স অ্যান্ড কন্ট্রোল', 'Kinematics, Dynamics, and Trajectory Generation (CSE 487)', '0133489795', '9780133489798', 87, 2017, '4th Edition', 'English', 'Covers spatial descriptions, forward and inverse kinematics of manipulators, Jacobians, manipulator dynamics, and linear/nonlinear control.'),
(286, 'Distributed Systems: Principles and Paradigms', 'ডিসট্রিবিউটেড সিস্টেমস: প্রিন্সিপলস অ্যান্ড প্যারাডাইমস', 'Communication, Naming, Synchronization, and Fault Tolerance (CSE 417)', '0132392275', '9780132392273', 87, 2006, '2nd Edition', 'English', 'Examines architectures, RPC, logical clocks, leader election, consistency and replication, fault tolerance, and distributed file systems.'),
(287, 'Parallel Programming: For Multicore and Cluster Systems', 'প্যারালেল প্রোগ্রামিং: ফর মাল্টিকোর অ্যান্ড ক্লাস্টার সিস্টেমস', 'MPI, OpenMP, and Pthreads Programming (CSE 485)', '3642378013', '9783642378010', 95, 2013, '2nd Edition', 'English', 'Covers parallel computer architectures, performance analysis, message passing with MPI, shared memory with OpenMP, and GPU computing.'),
(288, 'Introduction to Parallel Computing', 'ইন্ট্রোডাকশন টু প্যারালেল কম্পিউটিং', 'Design and Analysis of Parallel Algorithms (CSE 485)', '0201648652', '9780201648652', 35, 2003, '2nd Edition', 'English', 'Presents parallel algorithm design models, analytical modeling of parallel programs, collective communication, and parallel graph/sorting algorithms.'),
(289, 'Cryptography and Network Security: Principles and Practice', 'ক্রিপ্টোগ্রাফি অ্যান্ড নেটওয়ার্ক সিকিউরিটি', 'Ciphers, Hash Functions, and Internet Security (CSE 455)', '0134444280', '9780134444284', 87, 2016, '7th Edition', 'English', 'Comprehensive tutorial on AES, RSA, elliptic curve cryptography, cryptographic hash functions, digital signatures, and network security protocols.'),
(290, 'Security Engineering', 'সিকিউরিটি ইঞ্জিনিয়ারিং', 'A Guide to Building Dependable Distributed Systems (CSE 455)', '1119642787', '9781119642787', 91, 2020, '3rd Edition', 'English', 'Explores usability, psychology, access control, cryptography, hardware tamper resistance, banking security, and network attack defense.'),
(291, 'Applied Cryptography', 'অ্যাপ্লায়েড ক্রিপ্টোগ্রাফি', 'Protocols, Algorithms, and Source Code in C', '1119096723', '9781119096726', 91, 2015, '20th Anniversary Edition', 'English', 'Classic reference detailing cryptographic protocols, block ciphers, stream ciphers, key exchange, and real-world implementation pitfalls.'),
(292, 'Hacking: The Art of Exploitation', 'হ্যাকিং: দ্য আর্ট অব এক্সপ্লয়টেশন', 'Buffer Overflows, Shellcode, and Network Countermeasures', '1593271441', '9781593271442', 36, 2008, '2nd Edition', 'English', 'Hands-on introduction to the technical foundations of C memory corruption, assembly debugging with GDB, networking, shellcode, and cryptology.'),
(293, 'Management Information Systems', 'ম্যানেজমেন্ট ইনফরমেশন সিস্টেমস', 'Managing the Digital Firm (CSE 407)', '0135191793', '9780135191798', 87, 2019, '16th Edition', 'English', 'Examines how enterprise systems, business intelligence, cloud computing, and e-commerce transform modern organizations and decision-making.'),
(294, 'Systems Analysis and Design', 'সিস্টেমস অ্যানালাইসিস অ্যান্ড ডিজাইন', 'Human-Centered Information Systems Development (CSE 317)', '013478555X', '9780134785559', 87, 2019, '10th Edition', 'English', 'Presents structured, agile, and object-oriented methodologies for analyzing business requirements, data flow diagrams, and UI/UX design.'),
(295, 'The Mythical Man-Month', 'দ্য মিথিক্যাল ম্যান-মান্থ', 'Classic Essays on Software Engineering Management', '0201835959-2', '9780201835953-2', 35, 1995, '20th Anniversary Edition', 'English', 'Timeless insights on software project management, Brooks''s Law, the surgical team model, and the "No Silver Bullet" essay.'),
(296, 'The Practice of Programming', 'দ্য প্র্যাকটিস অব প্রোগ্রামিং', 'Simplicity, Clarity, and Generality in Software', '020161586X', '9780201615869', 35, 1999, '1st Edition', 'English', 'Practical guidance on coding style, algorithm selection, design, interfaces, debugging, testing, performance profiling, and portability.'),
(297, 'Code: The Hidden Language of Computer Hardware and Software', 'কোড: দ্য হিডেন ল্যাঙ্গুয়েজ অব কম্পিউটার হার্ডওয়্যার অ্যান্ড সফটওয়্যার', 'From Telegraph Relays to Modern Microprocessors', '0137909101', '9780137909100', 86, 2022, '2nd Edition', 'English', 'Illustrated journey showing how binary codes, Boolean logic gates, flip-flops, and assembly instructions build a complete working computer.'),
(298, 'Computer Systems: A Programmer''s Perspective', 'কম্পিউটার সিস্টেমস: আ প্রোগ্রামার্স পার্সপেক্টিভ', 'How Hardware, OS, and Compilers Execute Programs', '013409266X', '9780134092669', 87, 2015, '3rd Edition', 'English', 'Explains data representations, x86-64 machine-level code, processor architecture, memory hierarchy, linking, virtual memory, and system-level I/O.'),
(299, 'An Introduction to Information Theory', 'অ্যান ইন্ট্রোডাকশন টু ইনফরমেশন থিওরি', 'Symbols, Signals and Noise', '0486240614', '9780486240619', 101, 1980, '2nd Revised Edition', 'English', 'Accessible explanation of Claude Shannon''s information theory, entropy, channel capacity, error-correcting codes, and communication theory.'),
(300, 'Computer Security: Principles and Practice', 'কম্পিউটার সিকিউরিটি: প্রিন্সিপলস অ্যান্ড প্র্যাকটিস', 'Comprehensive Defense of Software and Systems (CSE 455)', '0133773922', '9780133773927', 87, 2017, '4th Edition', 'English', 'Covers user authentication, access control, malicious software, denial-of-service attacks, intrusion detection, buffer overflows, and cloud security.');

